import fs from 'node:fs/promises';
import fsSync from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const DEFAULT_DATA_DIR = path.resolve(__dirname, '../data');
const DEFAULT_DATA_FILE = path.join(DEFAULT_DATA_DIR, 'books.json');

export class BookStore {
  constructor(filePath = DEFAULT_DATA_FILE) {
    this.filePath = filePath;
    this.dirPath = path.dirname(filePath);
    this._initSync();
  }

  _initSync() {
    try {
      if (!fsSync.existsSync(this.dirPath)) {
        fsSync.mkdirSync(this.dirPath, { recursive: true });
      }
      if (!fsSync.existsSync(this.filePath)) {
        fsSync.writeFileSync(this.filePath, JSON.stringify([], null, 2), 'utf-8');
      }
    } catch (err) {
      console.error(`Failed to initialize data directory/file at ${this.filePath}:`, err);
    }
  }

  async _readAll() {
    try {
      await fs.mkdir(this.dirPath, { recursive: true });
      const content = await fs.readFile(this.filePath, 'utf-8');
      const data = JSON.parse(content);
      return Array.isArray(data) ? data : [];
    } catch (err) {
      if (err.code === 'ENOENT') {
        await this._writeAll([]);
        return [];
      }
      console.error(`Error reading books from ${this.filePath}:`, err);
      return [];
    }
  }

  async _writeAll(books) {
    await fs.mkdir(this.dirPath, { recursive: true });
    const tempFile = `${this.filePath}.${crypto.randomUUID()}.tmp`;
    const data = JSON.stringify(books, null, 2);
    await fs.writeFile(tempFile, data, 'utf-8');
    await fs.rename(tempFile, this.filePath);
  }

  async getAllBooks() {
    const books = await this._readAll();
    // Return newest first
    return books.sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
  }

  async getBookById(id) {
    const books = await this._readAll();
    return books.find((b) => b.id === id) || null;
  }

  async addBook({ title, author, notes = '', status = 'reading' }) {
    if (!title || !title.trim()) {
      throw new Error('Book title is required');
    }
    if (!author || !author.trim()) {
      throw new Error('Book author is required');
    }

    const validStatus = status === 'finished' ? 'finished' : 'reading';
    const now = new Date().toISOString();

    const newBook = {
      id: crypto.randomUUID(),
      title: title.trim(),
      author: author.trim(),
      notes: typeof notes === 'string' ? notes.trim() : '',
      status: validStatus,
      createdAt: now,
      updatedAt: now,
      finishedAt: validStatus === 'finished' ? now : null,
    };

    const books = await this._readAll();
    books.push(newBook);
    await this._writeAll(books);
    return newBook;
  }

  async updateBook(id, updates = {}) {
    const books = await this._readAll();
    const index = books.findIndex((b) => b.id === id);
    if (index === -1) {
      return null;
    }

    const existing = books[index];
    const updated = { ...existing };

    if (updates.title !== undefined) {
      const trimmed = updates.title.trim();
      if (!trimmed) throw new Error('Book title cannot be empty');
      updated.title = trimmed;
    }
    if (updates.author !== undefined) {
      const trimmed = updates.author.trim();
      if (!trimmed) throw new Error('Book author cannot be empty');
      updated.author = trimmed;
    }
    if (updates.notes !== undefined) {
      updated.notes = typeof updates.notes === 'string' ? updates.notes.trim() : '';
    }
    if (updates.status !== undefined) {
      const newStatus = updates.status === 'finished' ? 'finished' : 'reading';
      if (newStatus !== existing.status) {
        updated.status = newStatus;
        if (newStatus === 'finished') {
          updated.finishedAt = updates.finishedAt || new Date().toISOString();
        } else {
          updated.finishedAt = null;
        }
      }
    }

    updated.updatedAt = new Date().toISOString();
    books[index] = updated;
    await this._writeAll(books);
    return updated;
  }

  async markAsFinished(id) {
    return this.updateBook(id, {
      status: 'finished',
      finishedAt: new Date().toISOString(),
    });
  }

  async markAsReading(id) {
    return this.updateBook(id, {
      status: 'reading',
      finishedAt: null,
    });
  }

  async deleteBook(id) {
    const books = await this._readAll();
    const initialLen = books.length;
    const filtered = books.filter((b) => b.id !== id);
    if (filtered.length !== initialLen) {
      await this._writeAll(filtered);
      return true;
    }
    return false;
  }
}

export const defaultStore = new BookStore();

