    if (updates.author !== undefined) {
      const trimmed = updates.author.trim();
      if (!trimmed) throw new Error('Book author cannot be empty');
      updated.author = trimmed;
    }
    if (updates.notes !== undefined) {
      updated.notes = typeof updates.notes === 'string' ? updates.notes.trim() : '';
    }
    if (updates.status !== undefined) {
      const newStatus = updates.status === 'finished' ? 'finished' : 'reading';
      if (newStatus !== existing.status) {
        updated.status = newStatus;
        if (newStatus === 'finished') {
          updated.finishedAt = updates.finishedAt || new Date().toISOString();
        } else {
          updated.finishedAt = null;
        }
      }
    }

    updated.updatedAt = new Date().toISOString();
    books[index] = updated;
    await this._writeAll(books);
    return updated;
  }

  async markAsFinished(id) {
    return this.updateBook(id, {
      status: 'finished',
      finishedAt: new Date().toISOString(),
    });
  }

  async markAsReading(id) {
    return this.updateBook(id, {
      status: 'reading',
      finishedAt: null,
    });
  }

  async deleteBook(id) {
    const books = await this._readAll();
    const initialLen = books.length;
    const filtered = books.filter((b) => b.id !== id);
    if (filtered.length !== initialLen) {
      await this._writeAll(filtered);
      return true;
    }
    return false;
  }
}

export const defaultStore = new BookStore();

