args.content:
:root {
  --bg-page: #fbf9f5;
  --bg-surface: #ffffff;
  --bg-subtle: #f4efe6;
  --text-main: #1c1917;
  --text-secondary: #57534e;
  --text-muted: #78716c;
  --border-color: #e7e2d9;
  --border-focus: #c2410c;

  --primary: #c2410c;
  --primary-hover: #9a3412;
  --primary-light: #ffedd5;

  --reading-badge-bg: #fef3c7;
  --reading-badge-text: #92400e;
  --reading-indicator: #f59e0b;

  --finished-badge-bg: #ecfdf5;
  --finished-badge-text: #065f46;
  --finished-indicator: #10b981;

  --danger: #b91c1c;
  --danger-hover: #991b1b;
  --danger-light: #fee2e2;

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 12px -2px rgba(28, 25, 23, 0.06), 0 2px 6px -1px rgba(28, 25, 23, 0.03);
  --shadow-lg: 0 10px 24px -3px rgba(28, 25, 23, 0.08), 0 4px 10px -2px rgba(28, 25, 23, 0.03);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-page: #151413;
    --bg-surface: #1e1d1a;
    --bg-subtle: #272522;
    --text-main: #f5f4f0;
    --text-secondary: #d4d0c7;
    --text-muted: #a39e93;
    --border-color: #33312c;
    --border-focus: #ea580c;

    --primary: #ea580c;
    --primary-hover: #f97316;
    --primary-light: #3d2314;

    --reading-badge-bg: #382c14;
    --reading-badge-text: #fde68a;
    --reading-indicator: #fbbf24;

    --finished-badge-bg: #14352b;
    --finished-badge-text: #a7f3d0;
    --finished-indicator: #34d399;

    --danger: #ef4444;
    --danger-hover: #f87171;
    --danger-light: #3a1a1a;

    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 10px 24px rgba(0, 0, 0, 0.5);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.site-container {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 1.25rem 4rem 1.25rem;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Header */
.site-header {
  padding: 1.5rem 0;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 2rem;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  text-decoration: none;
  color: var(--text-main);
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: -0.02em;
}

.brand-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  background-color: var(--primary-light);
  color: var(--primary);
  border-radius: var(--radius-md);
}

.header-actions {
  display: flex;
  gap: 0.5rem;
}

/* Main Hero */
.hero-section {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 1.5rem;
  margin-bottom: 2.25rem;
  flex-wrap: wrap;
}

.hero-title {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 2.25rem;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 0.35rem;
}

.hero-subtitle {
  color: var(--text-secondary);
  font-size: 1.05rem;
}

.stats-pills {
  display: flex;
  gap: 0.75rem;
}

.stat-pill {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: 0.45rem 0.9rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  color: var(--text-secondary);
  box-shadow: var(--shadow-sm);
}

.stat-pill strong {
  color: var(--text-main);
  font-weight: 700;
  margin-right: 0.25rem;
}

/* Cards & Layout */
.card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}

/* Form */
.form-section {
  margin-bottom: 2.5rem;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 1.25rem;
}

.card-title {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 1.5rem;
  font-weight: 600;
}

.card-hint {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.book-form .form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.form-group {
  margin-bottom: 1.15rem;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 0.35rem;
}

.required {
  color: var(--primary);
}

input[type="text"],
textarea,
select {
  width: 100%;
  padding: 0.7rem 0.9rem;
  font-family: inherit;
  font-size: 0.95rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: var(--bg-surface);
  color: var(--text-main);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

input[type="text"]:focus,
textarea:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(194, 65, 12, 0.12);
}

textarea {
  resize: vertical;
  min-height: 80px;
}

.segmented-control {
  display: flex;
  gap: 0.5rem;
  background-color: var(--bg-subtle);
  padding: 0.25rem;
  border-radius: var(--radius-md);
  width: fit-content;
}

.radio-label {
  display: flex;
  align-items: center;
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  user-select: none;
  transition: background-color 0.15s, color 0.15s;
}

.radio-label input {
  display: none;
}

.radio-label:has(input:checked) {
  background-color: var(--bg-surface);
  color: var(--text-main);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.5rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.65rem 1.25rem;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  text-decoration: none;
  transition: all 0.15s ease;
  line-height: 1;
}

.btn-primary {
  background-color: var(--primary);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--border-color);
  color: var(--text-main);
}

.btn-outline:hover {
  background-color: var(--bg-subtle);
  border-color: var(--text-muted);
}

.btn-outline-success {
  background-color: transparent;
  border-color: #6ee7b7;
  color: #065f46;
}

.btn-outline-success:hover {
  background-color: var(--finished-badge-bg);
  border-color: #059669;
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 0.5rem 0.75rem;
}

.btn-ghost:hover {
  color: var(--primary);
  background: var(--primary-light);
}

.btn-ghost-danger {
  background: transparent;
  color: var(--danger);
  border: 1px solid transparent;
}

.btn-ghost-danger:hover {
  background: var(--danger-light);
  border-color: var(--danger);
}

.btn-sm {
  padding: 0.45rem 0.8rem;
  font-size: 0.825rem;
  border-radius: var(--radius-sm);
}

/* Lists Grid */
.lists-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.book-shelf {
  display: flex;
  flex-direction: column;
}

.shelf-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  padding-bottom: 0.65rem;
  border-bottom: 2px solid var(--border-color);
}

.shelf-title-wrap {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.shelf-title-wrap h2 {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 1.35rem;
  font-weight: 600;
}

.shelf-indicator {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.indicator-reading {
  background-color: var(--reading-indicator);
}

.indicator-finished {
  background-color: var(--finished-indicator);
}

.count-badge {
  background-color: var(--bg-subtle);
  color: var(--text-secondary);
  font-size: 0.785rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 9999px;
}

.shelf-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Book Cards */
.book-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 0.85rem;
  padding: 1.15rem 1.25rem;
}

.book-card:hover {
  border-color: #d1cbbf;
  box-shadow: var(--shadow-md);
}

.book-card-link {
  text-decoration: none;
  color: inherit;
  display: block;
}

.book-title {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 1.2rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-main);
  margin-bottom: 0.2rem;
  transition: color 0.15s;
}

.book-card-link:hover .book-title {
  color: var(--primary);
}

.book-author {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 0.5rem;
}

.book-notes-preview {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-style: italic;
  line-height: 1.4;
  margin-bottom: 0.65rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.book-meta {
  font-size: 0.775rem;
  color: var(--text-muted);
}

.book-card-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-color);
  gap: 0.5rem;
}

.inline-action-form {
  display: inline-block;
  margin: 0;
}

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.775rem;
  font-weight: 600;
  padding: 0.25rem 0.65rem;
  border-radius: 9999px;
  line-height: 1;
}

.badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: currentColor;
}

.badge-reading {
  background-color: var(--reading-badge-bg);
  color: var(--reading-badge-text);
}

.badge-success {
  background-color: var(--finished-badge-bg);
  color: var(--finished-badge-text);
}

/* Empty State */
.empty-state {
  text-align: center;
  padding: 2.5rem 1.5rem;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-lg);
  background-color: rgba(255, 255, 255, 0.4);
}

.empty-icon {
  font-size: 2rem;
  margin-bottom: 0.5rem;
  opacity: 0.7;
}

.empty-title {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-secondary);
  margin-bottom: 0.25rem;
}

.empty-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Detail Page */
.breadcrumb-nav {
  margin-bottom: 1.5rem;
}

.back-link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color 0.15s;
}

.back-link:hover {
  color: var(--primary);
}

.book-detail-card {
  padding: 2.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

.detail-header {
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 1.5rem;
}

.detail-status {
  margin-bottom: 0.75rem;
}

.detail-title {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 2.25rem;
  line-height: 1.2;
  margin-bottom: 0.4rem;
}

.detail-author {
  font-size: 1.15rem;
  color: var(--text-secondary);
  margin-bottom: 0.75rem;
}

.detail-timestamps {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.section-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 700;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

.notes-section {
  background-color: var(--bg-subtle);
  border-radius: var(--radius-md);
  padding: 1.5rem;
}

.notes-content {
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--text-main);
  white-space: pre-wrap;
}

.notes-content p {
  margin-bottom: 1rem;
}

.notes-content p:last-child {
  margin-bottom: 0;
}

.empty-notes {
  color: var(--text-muted);
  font-style: italic;
  font-size: 0.95rem;
}

/* Share Box */
.share-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  gap: 1rem;
  flex-wrap: wrap;
}

.share-info {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-secondary);
}

.share-text {
  display: flex;
  flex-direction: column;
}

.share-text strong {
  font-size: 0.875rem;
  color: var(--text-main);
}

.share-url-preview {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-family: monospace;
}

.detail-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 1rem;
  border-top: 1px solid var(--border-color);
  gap: 1rem;
  flex-wrap: wrap;
}

.status-actions {
  display: flex;
  gap: 0.75rem;
}

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background-color: #1c1917;
  color: #ffffff;
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  transform: translateY(12px);
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
  z-index: 1000;
}

.toast.show {
  opacity: 1;
  transform: translateY(0);
}

/* Footer */
.site-footer {
  margin-top: auto;
  padding-top: 3rem;
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Not Found */
.not-found {
  text-align: center;
  padding: 4rem 2rem;
}

.not-found h1 {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 2rem;
  margin-bottom: 0.75rem;
}

.not-found p {
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
}

/* Responsive */
@media (max-width: 768px) {
  .lists-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .book-form .form-grid {
    grid-template-columns: 1fr;
  }

  .hero-section {
    flex-direction: column;
    align-items: flex-start;
  }

  .book-detail-card {
    padding: 1.5rem;
  }

  .detail-title {
    font-size: 1.75rem;
  }
}

input.content:
:root {
  --bg-page: #fbf9f5;
  --bg-surface: #ffffff;
  --bg-subtle: #f4efe6;
  --text-main: #1c1917;
  --text-secondary: #57534e;
  --text-muted: #78716c;
  --border-color: #e7e2d9;
  --border-focus: #c2410c;

  --primary: #c2410c;
  --primary-hover: #9a3412;
  --primary-light: #ffedd5;

  --reading-badge-bg: #fef3c7;
  --reading-badge-text: #92400e;
  --reading-indicator: #f59e0b;

  --finished-badge-bg: #ecfdf5;
  --finished-badge-text: #065f46;
  --finished-indicator: #10b981;

  --danger: #b91c1c;
  --danger-hover: #991b1b;
  --danger-light: #fee2e2;

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 12px -2px rgba(28, 25, 23, 0.06), 0 2px 6px -1px rgba(28, 25, 23, 0.03);
  --shadow-lg: 0 10px 24px -3px rgba(28, 25, 23, 0.08), 0 4px 10px -2px rgba(28, 25, 23, 0.03);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-page: #151413;
    --bg-surface: #1e1d1a;
    --bg-subtle: #272522;
    --text-main: #f5f4f0;
    --text-secondary: #d4d0c7;
    --text-muted: #a39e93;
    --border-color: #33312c;
    --border-focus: #ea580c;

    --primary: #ea580c;
    --primary-hover: #f97316;
    --primary-light: #3d2314;

    --reading-badge-bg: #382c14;
    --reading-badge-text: #fde68a;
    --reading-indicator: #fbbf24;

    --finished-badge-bg: #14352b;
    --finished-badge-text: #a7f3d0;
    --finished-indicator: #34d399;

    --danger: #ef4444;
    --danger-hover: #f87171;
    --danger-light: #3a1a1a;

    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 10px 24px rgba(0, 0, 0, 0.5);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.site-container {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 1.25rem 4rem 1.25rem;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Header */
.site-header {
  padding: 1.5rem 0;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 2rem;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  text-decoration: none;
  color: var(--text-main);
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: -0.02em;
}

.brand-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  background-color: var(--primary-light);
  color: var(--primary);
  border-radius: var(--radius-md);
}

.header-actions {
  display: flex;
  gap: 0.5rem;
}

/* Main Hero */
.hero-section {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 1.5rem;
  margin-bottom: 2.25rem;
  flex-wrap: wrap;
}

.hero-title {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 2.25rem;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 0.35rem;
}

.hero-subtitle {
  color: var(--text-secondary);
  font-size: 1.05rem;
}

.stats-pills {
  display: flex;
  gap: 0.75rem;
}

.stat-pill {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: 0.45rem 0.9rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  color: var(--text-secondary);
  box-shadow: var(--shadow-sm);
}

.stat-pill strong {
  color: var(--text-main);
  font-weight: 700;
  margin-right: 0.25rem;
}

/* Cards & Layout */
.card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}

/* Form */
.form-section {
  margin-bottom: 2.5rem;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 1.25rem;
}

.card-title {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 1.5rem;
  font-weight: 600;
}

.card-hint {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.book-form .form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.form-group {
  margin-bottom: 1.15rem;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 0.35rem;
}

.required {
  color: var(--primary);
}

input[type="text"],
textarea,
select {
  width: 100%;
  padding: 0.7rem 0.9rem;
  font-family: inherit;
  font-size: 0.95rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: var(--bg-surface);
  color: var(--text-main);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

input[type="text"]:focus,
textarea:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(194, 65, 12, 0.12);
}

textarea {
  resize: vertical;
  min-height: 80px;
}

.segmented-control {
  display: flex;
  gap: 0.5rem;
  background-color: var(--bg-subtle);
  padding: 0.25rem;
  border-radius: var(--radius-md);
  width: fit-content;
}

.radio-label {
  display: flex;
  align-items: center;
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  user-select: none;
  transition: background-color 0.15s, color 0.15s;
}

.radio-label input {
  display: none;
}

.radio-label:has(input:checked) {
  background-color: var(--bg-surface);
  color: var(--text-main);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.5rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.65rem 1.25rem;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  text-decoration: none;
  transition: all 0.15s ease;
  line-height: 1;
}

.btn-primary {
  background-color: var(--primary);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--border-color);
  color: var(--text-main);
}

.btn-outline:hover {
  background-color: var(--bg-subtle);
  border-color: var(--text-muted);
}

.btn-outline-success {
  background-color: transparent;
  border-color: #6ee7b7;
  color: #065f46;
}

.btn-outline-success:hover {
  background-color: var(--finished-badge-bg);
  border-color: #059669;
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 0.5rem 0.75rem;
}

.btn-ghost:hover {
  color: var(--primary);
  background: var(--primary-light);
}

.btn-ghost-danger {
  background: transparent;
  color: var(--danger);
  border: 1px solid transparent;
}

.btn-ghost-danger:hover {
  background: var(--danger-light);
  border-color: var(--danger);
}

.btn-sm {
  padding: 0.45rem 0.8rem;
  font-size: 0.825rem;
  border-radius: var(--radius-sm);
}

/* Lists Grid */
.lists-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.book-shelf {
  display: flex;
  flex-direction: column;
}

.shelf-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  padding-bottom: 0.65rem;
  border-bottom: 2px solid var(--border-color);
}

.shelf-title-wrap {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.shelf-title-wrap h2 {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 1.35rem;
  font-weight: 600;
}

.shelf-indicator {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.indicator-reading {
  background-color: var(--reading-indicator);
}

.indicator-finished {
  background-color: var(--finished-indicator);
}

.count-badge {
  background-color: var(--bg-subtle);
  color: var(--text-secondary);
  font-size: 0.785rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 9999px;
}

.shelf-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Book Cards */
.book-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 0.85rem;
  padding: 1.15rem 1.25rem;
}

.book-card:hover {
  border-color: #d1cbbf;
  box-shadow: var(--shadow-md);
}

.book-card-link {
  text-decoration: none;
  color: inherit;
  display: block;
}

.book-title {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 1.2rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-main);
  margin-bottom: 0.2rem;
  transition: color 0.15s;
}

.book-card-link:hover .book-title {
  color: var(--primary);
}

.book-author {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 0.5rem;
}

.book-notes-preview {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-style: italic;
  line-height: 1.4;
  margin-bottom: 0.65rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.book-meta {
  font-size: 0.775rem;
  color: var(--text-muted);
}

.book-card-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-color);
  gap: 0.5rem;
}

.inline-action-form {
  display: inline-block;
  margin: 0;
}

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.775rem;
  font-weight: 600;
  padding: 0.25rem 0.65rem;
  border-radius: 9999px;
  line-height: 1;
}

.badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: currentColor;
}

.badge-reading {
  background-color: var(--reading-badge-bg);
  color: var(--reading-badge-text);
}

.badge-success {
  background-color: var(--finished-badge-bg);
  color: var(--finished-badge-text);
}

/* Empty State */
.empty-state {
  text-align: center;
  padding: 2.5rem 1.5rem;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-lg);
  background-color: rgba(255, 255, 255, 0.4);
}

.empty-icon {
  font-size: 2rem;
  margin-bottom: 0.5rem;
  opacity: 0.7;
}

.empty-title {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-secondary);
  margin-bottom: 0.25rem;
}

.empty-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Detail Page */
.breadcrumb-nav {
  margin-bottom: 1.5rem;
}

.back-link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color 0.15s;
}

.back-link:hover {
  color: var(--primary);
}

.book-detail-card {
  padding: 2.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

.detail-header {
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 1.5rem;
}

.detail-status {
  margin-bottom: 0.75rem;
}

.detail-title {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 2.25rem;
  line-height: 1.2;
  margin-bottom: 0.4rem;
}

.detail-author {
  font-size: 1.15rem;
  color: var(--text-secondary);
  margin-bottom: 0.75rem;
}

.detail-timestamps {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.section-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 700;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

.notes-section {
  background-color: var(--bg-subtle);
  border-radius: var(--radius-md);
  padding: 1.5rem;
}

.notes-content {
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--text-main);
  white-space: pre-wrap;
}

.notes-content p {
  margin-bottom: 1rem;
}

.notes-content p:last-child {
  margin-bottom: 0;
}

.empty-notes {
  color: var(--text-muted);
  font-style: italic;
  font-size: 0.95rem;
}

/* Share Box */
.share-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  gap: 1rem;
  flex-wrap: wrap;
}

.share-info {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-secondary);
}

.share-text {
  display: flex;
  flex-direction: column;
}

.share-text strong {
  font-size: 0.875rem;
  color: var(--text-main);
}

.share-url-preview {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-family: monospace;
}

.detail-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 1rem;
  border-top: 1px solid var(--border-color);
  gap: 1rem;
  flex-wrap: wrap;
}

.status-actions {
  display: flex;
  gap: 0.75rem;
}

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background-color: #1c1917;
  color: #ffffff;
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  transform: translateY(12px);
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
  z-index: 1000;
}

.toast.show {
  opacity: 1;
  transform: translateY(0);
}

/* Footer */
.site-footer {
  margin-top: auto;
  padding-top: 3rem;
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Not Found */
.not-found {
  text-align: center;
  padding: 4rem 2rem;
}

.not-found h1 {
  font-family: 'Newsreader', Georgia, serif;
  font-size: 2rem;
  margin-bottom: 0.75rem;
}

.not-found p {
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
}

/* Responsive */
@media (max-width: 768px) {
  .lists-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .book-form .form-grid {
    grid-template-columns: 1fr;
  }

  .hero-section {
    flex-direction: column;
    align-items: flex-start;
  }

  .book-detail-card {
    padding: 1.5rem;
  }

  .detail-title {
    font-size: 1.75rem;
  }
}

