import express from 'express';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { defaultStore } from './storage.js';
import { renderHomePage, renderBookPage, renderNotFoundPage } from './views.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const publicDir = path.resolve(__dirname, '../public');

export function createApp(store = defaultStore) {
  const app = express();

  app.use(express.urlencoded({ extended: true }));
  app.use(express.json());
  app.use(express.static(publicDir));

  // --- HTML Page Routes ---

  // Home: See what's currently reading and what is finished
  app.get('/', async (req, res, next) => {
    try {
      const books = await store.getAllBooks();
      const readingBooks = books.filter((b) => b.status === 'reading');
      const finishedBooks = books.filter((b) => b.status === 'finished');
      const html = renderHomePage({ readingBooks, finishedBooks });
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      res.send(html);
    } catch (err) {
      next(err);
    }
  });

  // Single Book: View title, author, notes, and shareable link
  app.get('/books/:id', async (req, res, next) => {
    try {
      const book = await store.getBookById(req.params.id);
      if (!book) {
        res.status(404);
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        return res.send(renderNotFoundPage());
      }
      const baseUrl = `${req.protocol}://${req.get('host')}`;
      const html = renderBookPage(book, baseUrl);
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      res.send(html);
    } catch (err) {
      next(err);
    }
  });

  // Add a book from form
  app.post('/books', async (req, res, next) => {
    try {
      const { title, author, notes, status } = req.body;
      if (!title || !author) {
        return res.status(400).send('Title and Author are required');
      }
      const book = await store.addBook({
        title,
        author,
        notes,
        status: status === 'finished' ? 'finished' : 'reading',
      });
      // Redirect to home page or book detail
      res.redirect('/');
    } catch (err) {
      next(err);
    }
  });

  // Mark a book as finished
  app.post('/books/:id/finish', async (req, res, next) => {
    try {
      const updated = await store.markAsFinished(req.params.id);
      if (!updated) {
        return res.status(404).send(renderNotFoundPage());
      }
      const referer = req.get('Referer') || '/';
      res.redirect(referer);
    } catch (err) {
      next(err);
    }
  });

  // Mark a book back as reading
  app.post('/books/:id/reading', async (req, res, next) => {
    try {
      const updated = await store.markAsReading(req.params.id);
      if (!updated) {
        return res.status(404).send(renderNotFoundPage());
      }
      const referer = req.get('Referer') || `/books/${req.params.id}`;
      res.redirect(referer);
    } catch (err) {
      next(err);
    }
  });

  // Delete a book
  app.post('/books/:id/delete', async (req, res, next) => {
    try {
      await store.deleteBook(req.params.id);
      res.redirect('/');
    } catch (err) {
      next(err);
    }
  });

  // --- JSON API Endpoints ---

  app.get('/api/books', async (req, res, next) => {
