import { createApp } from './app.js';
import { defaultStore } from './storage.js';

const PORT = process.env.PORT || 3000;
const app = createApp(defaultStore);

const server = app.listen(PORT, () => {
  console.log(`📚 Book Tracker is running at http://localhost:${PORT}`);
  console.log(`📂 Storing books in ${defaultStore.filePath}`);
});

process.on('SIGINT', () => {
  server.close(() => {
    process.exit(0);
  });
});

process.on('SIGTERM', () => {
  server.close(() => {
    process.exit(0);
  });
});

