import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { BookStore } from '../src/storage.js';

describe('BookStore JSON persistence', () => {
  let tempDir;
  let testFilePath;
  let store;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'bookstore-test-'));
    testFilePath = path.join(tempDir, 'books.json');
    store = new BookStore(testFilePath);
  });

  afterEach(async () => {
    try {
      await fs.rm(tempDir, { recursive: true, force: true });
    } catch {
      // ignore
    }
  });

  it('initializes with an empty array if file does not exist', async () => {
    const books = await store.getAllBooks();
    expect(books).toEqual([]);
  });

  it('adds a book and persists it into the JSON file', async () => {
    const book = await store.addBook({
      title: 'Klara and the Sun',
      author: 'Kazuo Ishiguro',
      notes: 'Thought-provoking look at love and AI.',
    });

    expect(book.id).toBeDefined();
    expect(book.title).toBe('Klara and the Sun');
    expect(book.author).toBe('Kazuo Ishiguro');
    expect(book.status).toBe('reading');
    expect(book.notes).toBe('Thought-provoking look at love and AI.');
    expect(book.finishedAt).toBeNull();

    // Read directly from disk to verify JSON format
    const rawContent = await fs.readFile(testFilePath, 'utf-8');
    const parsed = JSON.parse(rawContent);
    expect(parsed.length).toBe(1);
    expect(parsed[0].title).toBe('Klara and the Sun');
  });

  it('persists data across restarts (new instance on same file)', async () => {
    await store.addBook({
      title: 'Project Hail Mary',
      author: 'Andy Weir',
      notes: 'Fascinating space survival.',
    });

    // Simulate restart with fresh BookStore instance
    const restartedStore = new BookStore(testFilePath);
    const books = await restartedStore.getAllBooks();

    expect(books.length).toBe(1);
    expect(books[0].title).toBe('Project Hail Mary');
    expect(books[0].author).toBe('Andy Weir');
  });

  it('marks a book as finished with a timestamp', async () => {
    const book = await store.addBook({
      title: 'Atomic Habits',
      author: 'James Clear',
      notes: 'Make it obvious, attractive, easy, satisfying.',
    });

    const finishedBook = await store.markAsFinished(book.id);
    expect(finishedBook.status).toBe('finished');
    expect(finishedBook.finishedAt).toBeTruthy();

    const fetched = await store.getBookById(book.id);
    expect(fetched.status).toBe('finished');
  });

  it('can mark a book back to reading', async () => {
    const book = await store.addBook({
      title: 'Deep Work',
      author: 'Cal Newport',
      status: 'finished',
    });
    expect(book.status).toBe('finished');

    const readingBook = await store.markAsReading(book.id);
    expect(readingBook.status).toBe('reading');
    expect(readingBook.finishedAt).toBeNull();
  });

  it('deletes a book and updates the JSON file', async () => {
    const book = await store.addBook({
      title: 'To Be Deleted',
      author: 'Unknown',
    });

    const deleted = await store.deleteBook(book.id);
    expect(deleted).toBe(true);

    const books = await store.getAllBooks();
    expect(books.length).toBe(0);
  });
});

