import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import request from 'supertest';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { BookStore } from '../src/storage.js';
import { createApp } from '../src/app.js';

describe('Book Tracker App Routes & API', () => {
  let tempDir;
  let testFilePath;
  let store;
  let app;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'book-app-test-'));
    testFilePath = path.join(tempDir, 'books.json');
    store = new BookStore(testFilePath);
    app = createApp(store);
  });

  afterEach(async () => {
    try {
      await fs.rm(tempDir, { recursive: true, force: true });
    } catch {
      // ignore
    }
  });

  describe('Page Rendering', () => {
    it('renders home page with Currently Reading and Finished sections', async () => {
      await store.addBook({
        title: 'Dune',
        author: 'Frank Herbert',
        status: 'reading',
        notes: 'Spice must flow.',
      });

      await store.addBook({
        title: 'Neuromancer',
        author: 'William Gibson',
        status: 'finished',
        notes: 'Cyberspace pioneer.',
      });

      const res = await request(app).get('/');
      expect(res.status).toBe(200);
      expect(res.headers['content-type']).toMatch(/text\/html/);
      expect(res.text).toContain('Currently Reading');
      expect(res.text).toContain('Finished');
      expect(res.text).toContain('Dune');
      expect(res.text).toContain('Frank Herbert');
      expect(res.text).toContain('Neuromancer');
      expect(res.text).toContain('William Gibson');
    });

    it('renders single book page with title, author, notes and share link preview', async () => {
      const book = await store.addBook({
        title: 'The Hobbit',
        author: 'J.R.R. Tolkien',
        notes: 'In a hole in the ground there lived a hobbit.',
      });

      const res = await request(app).get(`/books/${book.id}`);
      expect(res.status).toBe(200);
      expect(res.headers['content-type']).toMatch(/text\/html/);
      expect(res.text).toContain('The Hobbit');
      expect(res.text).toContain('J.R.R. Tolkien');
      expect(res.text).toContain('In a hole in the ground there lived a hobbit.');
      expect(res.text).toContain(`books/${book.id}`);
      expect(res.text).toContain('Copy Link');
    });

    it('returns 404 for unknown book id', async () => {
      const res = await request(app).get('/books/non-existent-id');
      expect(res.status).toBe(404);
      expect(res.text).toContain('Book Not Found');
    });
  });

  describe('Form Actions', () => {
    it('adds a book via POST /books form and redirects to /', async () => {
      const res = await request(app)
        .post('/books')
        .type('form')
        .send({
          title: 'Snow Crash',
          author: 'Neal Stephenson',
          notes: 'Metaverse origin novel.',
          status: 'reading',
        });

      expect(res.status).toBe(302);
      expect(res.headers.location).toBe('/');

      const books = await store.getAllBooks();
      expect(books.length).toBe(1);
      expect(books[0].title).toBe('Snow Crash');
      expect(books[0].author).toBe('Neal Stephenson');
      expect(books[0].notes).toBe('Metaverse origin novel.');
      expect(books[0].status).toBe('reading');
    });

    it('marks a book as finished via POST /books/:id/finish', async () => {
      const book = await store.addBook({
        title: 'Foundation',
        author: 'Isaac Asimov',
        status: 'reading',
      });

      const res = await request(app)
        .post(`/books/${book.id}/finish`)
        .set('Referer', '/');

      expect(res.status).toBe(302);

      const updated = await store.getBookById(book.id);
      expect(updated.status).toBe('finished');
      expect(updated.finishedAt).toBeTruthy();
    });

    it('deletes a book via POST /books/:id/delete', async () => {
      const book = await store.addBook({
        title: 'Temporary Book',
        author: 'Tester',
      });

      const res = await request(app).post(`/books/${book.id}/delete`);
      expect(res.status).toBe(302);
      expect(res.headers.location).toBe('/');

      const check = await store.getBookById(book.id);
      expect(check).toBeNull();
    });
  });

  describe('JSON API', () => {
    it('GET /api/books returns list of books', async () => {
      await store.addBook({ title: 'Book 1', author: 'Author 1' });
      await store.addBook({ title: 'Book 2', author: 'Author 2' });

      const res = await request(app).get('/api/books');
      expect(res.status).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBe(2);
    });

    it('POST /api/books creates a book', async () => {
      const res = await request(app)
        .post('/api/books')
        .send({
          title: 'Clean Code',
          author: 'Robert C. Martin',
          notes: 'Clean code always looks like it was written by someone who cares.',
        });

      expect(res.status).toBe(201);
      expect(res.body.title).toBe('Clean Code');
      expect(res.body.status).toBe('reading');
    });

    it('POST /api/books/:id/finish marks as finished', async () => {
      const book = await store.addBook({ title: '1984', author: 'George Orwell' });
      const res = await request(app).post(`/api/books/${book.id}/finish`);

      expect(res.status).toBe(200);
      expect(res.body.status).toBe('finished');
      expect(res.body.finishedAt).toBeTruthy();
    });

    it('DELETE /api/books/:id removes the book', async () => {
      const book = await store.addBook({ title: 'Fahrenheit 451', author: 'Ray Bradbury' });
      const res = await request(app).delete(`/api/books/${book.id}`);

      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
    });
  });

  describe('Persistence across restarts', () => {
    it('data remains available when a new app instance starts with the same JSON file', async () => {
      // 1. Create book in first instance
      await request(app)
        .post('/api/books')
        .send({
          title: 'Thinking, Fast and Slow',
          author: 'Daniel Kahneman',
          notes: 'System 1 and System 2.',
        });

      // 2. Spin up brand new BookStore and App instance on same JSON file (simulating server restart)
      const freshStore = new BookStore(testFilePath);
      const freshApp = createApp(freshStore);

      const res = await request(freshApp).get('/api/books');
      expect(res.status).toBe(200);
      expect(res.body.length).toBe(1);
      expect(res.body[0].title).toBe('Thinking, Fast and Slow');

      // Also verify HTML render on restarted server
      const htmlRes = await request(freshApp).get('/');
      expect(htmlRes.status).toBe(200);
      expect(htmlRes.text).toContain('Thinking, Fast and Slow');
    });
  });
});

